# 🎯 PER-FILL ACCUMULATOR CLASS - Her fill'in kendi entry fiyatı ile takibi
class PerFillAccumulator:
    """
    WebSocket ORDER_TRADE_UPDATE event'lerinden gelen fill'leri
    HER FILL'İN KENDI ENTRY FİYATI İLE sakla.

    KRITIK: 'L' değeri = bu event'de fill edilen parçanın entry fiyatı
    Phase 2 partial close için FIFO logic kullanılır.
    """

    def __init__(self, trading_pair: str, position_side: str):
        self.trading_pair = trading_pair
        self.position_side = position_side  # LONG veya SHORT
        self.fills: List[Dict] = (
            []
        )  # FIFO queue: [{qty, entry, timestamp, order_id, remaining_qty}]
        self.total_qty = Decimal("0")
        self.creation_time = time.time()

    def add_fill(
        self, fill_qty: Decimal, fill_entry: Decimal, timestamp: int, order_id: int
    ) -> None:
        """
        Yeni fill ekle - HER FILL'İN KENDI ENTRY FİYATI İLE

        Args:
            fill_qty: order.get('l') - bu event'de fill edilen miktar
            fill_entry: order.get('L') - bu event'de fill edilen fiyat (ENTRY!)
            timestamp: order.get('T')
            order_id: order.get('i')
        """
        fill_qty = Decimal(str(fill_qty))
        fill_entry = Decimal(str(fill_entry))

        fill_record = {
            "qty": fill_qty,
            "entry": fill_entry,  # HER FILL'İN KENDI ENTRY'Sİ!
            "timestamp": timestamp,
            "order_id": order_id,
            "remaining_qty": fill_qty,  # Partial close için
            "filled_at": time.time(),
        }

        self.fills.append(fill_record)
        self.total_qty += fill_qty

    def get_open_fills(self) -> List[Dict]:
        """Halen açık (kısmen kapanmamış) fill'leri döndür"""
        return [f for f in self.fills if f["remaining_qty"] > Decimal("0")]

    def close_amount_fifo(self, close_qty: Decimal) -> List[Dict]:
        """
        FIFO logic: kapatılan parçaların detayını döndür

        Returns:
            [{qty: kapanan miktar, entry: o fill'in entry, timestamp}]
        """
        close_qty = Decimal(str(close_qty))
        closed_fills = []
        remaining_to_close = close_qty

        for fill in self.fills:
            if remaining_to_close <= Decimal("0"):
                break

            available = fill["remaining_qty"]
            if available > Decimal("0"):
                close_this_fill = min(available, remaining_to_close)

                closed_fills.append(
                    {
                        "qty": close_this_fill,
                        "entry": fill["entry"],  # GERÇEK ENTRY FİYATI!
                        "timestamp": fill["timestamp"],
                        "order_id": fill["order_id"],
                        "remaining_after": fill["remaining_qty"] - close_this_fill,
                        "remaining_before": fill["remaining_qty"],
                    }
                )

                fill["remaining_qty"] -= close_this_fill
                remaining_to_close -= close_this_fill

        # YETERLI FILL YOKSA ROLLBACK (total_qty negatifleşmesin)
        if remaining_to_close > Decimal("0"):
            for closed in closed_fills:
                for fill in self.fills:
                    if fill["order_id"] == closed["order_id"]:
                        fill["remaining_qty"] += closed["qty"]
                        break
            closed_fills.clear()
            return closed_fills

        # Yeterli kapanma yapıldıysa gerçek kapanan kadar düş
        total_closed = close_qty - remaining_to_close
        self.total_qty -= total_closed
        return closed_fills

    def get_average_cost(self) -> Decimal:
        """Toplam açık pozun ortalama cost basis'i (per-fill bazında)"""
        if self.total_qty == 0:
            return Decimal("0")

        total_cost = sum(
            f["remaining_qty"] * f["entry"]
            for f in self.fills
            if f["remaining_qty"] > Decimal("0")
        )
        total_open_qty = sum(f["remaining_qty"] for f in self.fills)

        if total_open_qty == 0:
            return Decimal("0")

        return (total_cost / total_open_qty).quantize(Decimal("1E-8"))

    def get_position_details(self) -> Dict:
        """Detaylı pozisyon bilgisi - Phase 2 ve partial close için"""
        open_fills = self.get_open_fills()
        return {
            "trading_pair": self.trading_pair,
            "position_side": self.position_side,
            "total_qty": self.total_qty,
            "avg_cost": self.get_average_cost(),
            "fills_count": len(self.fills),
            "open_fills_count": len(open_fills),
            "open_fills": open_fills,
            "total_filled": sum(f["qty"] for f in self.fills),
            "creation_time": self.creation_time,
        }

    def preview_close(self, close_qty: Decimal) -> List[Dict]:
        """
        PREVIEW: Kapatılacak fill'leri göster (actual close yapmadan)
        Order göndermeden önce hangi fill'lerin etkileneceğini görmek için.

        Returns:
            [{qty: kapanacak miktar, entry: o fill'in entry, pnl_per_unit: birim başı pnl}]
        """
        close_qty = Decimal(str(close_qty))
        preview_fills = []
        remaining_to_close = close_qty

        for fill in self.fills:
            if remaining_to_close <= Decimal("0"):
                break

            available = fill["remaining_qty"]
            if available > Decimal("0"):
                close_this_fill = min(available, remaining_to_close)
                preview_fills.append(
                    {
                        "qty": close_this_fill,
                        "entry": fill["entry"],
                        "timestamp": fill["timestamp"],
                        "order_id": fill["order_id"],
                        "original_qty": fill["qty"],
                        "will_fully_close": close_this_fill >= available,
                    }
                )
                remaining_to_close -= close_this_fill

        return preview_fills

    def rollback_close(self, closed_fills: List[Dict]) -> None:
        """
        ROLLBACK: Order başarısız olursa fill'leri geri ekle.
        close_amount_fifo() sonrası rollback için kullanılır.

        Args:
            closed_fills: close_amount_fifo()'dan dönen liste
        """
        for closed in closed_fills:
            qty_to_restore = closed["qty"]
            order_id = closed["order_id"]

            # Aynı order_id'li fill'i bul ve remaining_qty'yi geri artır
            for fill in self.fills:
                if fill["order_id"] == order_id:
                    fill["remaining_qty"] += qty_to_restore
                    self.total_qty += qty_to_restore
                    break

    def validate_state(self) -> bool:
        """
        🔍 STATE VALIDATION: Accumulator state'in tutarlılığını kontrol et.
        Data corruption erken tespit için.

        Returns:
            True if state is valid, False if corrupted
        """
        # total_qty == sum(remaining_qty) olmalı
        calculated_qty = sum(f["remaining_qty"] for f in self.fills)

        # Tolerance: Decimal precision issues için küçük fark kabul
        tolerance = Decimal("0.000001")

        if abs(calculated_qty - self.total_qty) > tolerance:
            return False

        # remaining_qty hiçbir zaman negatif olamaz
        for fill in self.fills:
            if fill["remaining_qty"] < Decimal("0"):
                return False

        return True

    def is_stale(self, max_age_seconds: int = 300) -> bool:
        """
        🧹 STALE CHECK: Accumulator eski ve boş mu?
        Memory leak önleme için cleanup'ta kullanılır.

        Args:
            max_age_seconds: Maximum yaş (default 5 dakika)

        Returns:
            True if stale and can be cleaned up
        """
        if self.total_qty > Decimal("0"):
            return False  # Aktif pozisyon var, temizleme

        age = time.time() - self.creation_time
        return age > max_age_seconds

    def reset(self) -> None:
        """Accumulator'ı sıfırla (pozisyon kapanırken)"""
        self.fills.clear()
        self.total_qty = Decimal("0")

    # ============================================================================
    # 🎯 ORDER_ID BAZLI METODLAR - Multi-Position Yönetimi İçin
    # ============================================================================

    def get_fills_by_order_id(self, order_id: int) -> List[Dict]:
        """
        Belirli order_id'ye ait tüm fill'leri getir.

        Args:
            order_id: Hedef order ID

        Returns:
            Bu order'a ait fill listesi
        """
        return [f for f in self.fills if f["order_id"] == order_id]

    def get_open_fills_by_order_id(self, order_id: int) -> List[Dict]:
        """
        Belirli order_id'ye ait AÇIK fill'leri getir.

        Args:
            order_id: Hedef order ID

        Returns:
            Remaining_qty > 0 olan fill listesi
        """
        return [
            f
            for f in self.fills
            if f["order_id"] == order_id and f["remaining_qty"] > Decimal("0")
        ]

    def get_qty_by_order_id(self, order_id: int) -> Decimal:
        """
        Belirli order_id için toplam açık miktar.

        Args:
            order_id: Hedef order ID

        Returns:
            Bu order'ın toplam remaining quantity'si
        """
        return sum(f["remaining_qty"] for f in self.fills if f["order_id"] == order_id)

    def get_average_entry_by_order_id(self, order_id: int) -> Decimal:
        """
        Belirli order_id için ortalama entry fiyatı.

        Args:
            order_id: Hedef order ID

        Returns:
            Weighted average entry price
        """
        order_fills = [
            f
            for f in self.fills
            if f["order_id"] == order_id and f["remaining_qty"] > Decimal("0")
        ]

        if not order_fills:
            return Decimal("0")

        total_qty = sum(f["remaining_qty"] for f in order_fills)
        if total_qty == Decimal("0"):
            return Decimal("0")

        total_cost = sum(f["remaining_qty"] * f["entry"] for f in order_fills)
        return (total_cost / total_qty).quantize(Decimal("0.00000001"))

    def close_amount_fifo_by_order_id(
        self, close_qty: Decimal, order_id: int
    ) -> List[Dict]:
        """
        SADECE belirli order_id'ye ait fill'lerden FIFO kapatma.
        Multi-position yönetiminde order izolasyonu için KRİTİK!

        Args:
            close_qty: Kapatılacak miktar
            order_id: Hedef order ID

        Returns:
            [{qty: kapanan miktar, entry: fill entry, timestamp, order_id}]
        """
        close_qty = Decimal(str(close_qty))
        closed_fills = []
        remaining_to_close = close_qty

        # Sadece bu order'a ait fill'leri FIFO sırasıyla işle
        for fill in self.fills:
            if remaining_to_close <= Decimal("0"):
                break

            # SADECE hedef order_id'ye ait fill'leri işle
            if fill["order_id"] != order_id:
                continue

            available = fill["remaining_qty"]
            if available > Decimal("0"):
                close_this_fill = min(available, remaining_to_close)

                closed_fills.append(
                    {
                        "qty": close_this_fill,
                        "entry": fill["entry"],
                        "timestamp": fill["timestamp"],
                        "order_id": fill["order_id"],
                    }
                )

                fill["remaining_qty"] -= close_this_fill
                remaining_to_close -= close_this_fill
                self.total_qty -= close_this_fill

        return closed_fills

    def preview_close_by_order_id(
        self, close_qty: Decimal, order_id: int
    ) -> List[Dict]:
        """
        PREVIEW: Belirli order_id için kapatılacak fill'leri göster.

        Args:
            close_qty: Kapatılacak miktar
            order_id: Hedef order ID

        Returns:
            Preview listesi (actual close yapmadan)
        """
        close_qty = Decimal(str(close_qty))
        preview_fills = []
        remaining_to_close = close_qty

        for fill in self.fills:
            if remaining_to_close <= Decimal("0"):
                break

            if fill["order_id"] != order_id:
                continue

            available = fill["remaining_qty"]
            if available > Decimal("0"):
                close_this_fill = min(available, remaining_to_close)
                preview_fills.append(
                    {
                        "qty": close_this_fill,
                        "entry": fill["entry"],
                        "timestamp": fill["timestamp"],
                        "order_id": fill["order_id"],
                        "original_qty": fill["qty"],
                        "will_fully_close": close_this_fill >= available,
                    }
                )
                remaining_to_close -= close_this_fill

        return preview_fills

    def get_all_order_ids(self) -> List[int]:
        """
        Bu accumulator'daki tüm benzersiz order_id'leri getir.

        Returns:
            Unique order_id listesi (eski->yeni sıralı)
        """
        seen = []
        for fill in self.fills:
            if fill["order_id"] not in seen:
                seen.append(fill["order_id"])
        return seen

    def remove_order_fills(self, order_id: int) -> Decimal:
        """
        Belirli order_id'ye ait TÜM fill'leri kaldır.
        Pozisyon tam kapandığında kullanılır.

        Args:
            order_id: Silinecek order ID

        Returns:
            Silinen toplam quantity
        """
        removed_qty = Decimal("0")
        new_fills = []

        for fill in self.fills:
            if fill["order_id"] == order_id:
                removed_qty += fill["remaining_qty"]
            else:
                new_fills.append(fill)

        self.fills = new_fills
        self.total_qty -= removed_qty

        return removed_qty

    def get_order_position_details(self, order_id: int) -> Dict:
        """
        Belirli order_id için detaylı pozisyon bilgisi.

        Args:
            order_id: Hedef order ID

        Returns:
            Position details dict
        """
        order_fills = self.get_fills_by_order_id(order_id)
        open_fills = self.get_open_fills_by_order_id(order_id)

        return {
            "order_id": order_id,
            "trading_pair": self.trading_pair,
            "position_side": self.position_side,
            "total_qty": self.get_qty_by_order_id(order_id),
            "avg_entry": self.get_average_entry_by_order_id(order_id),
            "fills_count": len(order_fills),
            "open_fills_count": len(open_fills),
            "open_fills": open_fills,
        }

    def has_order_fills(self, order_id: int) -> bool:
        """
        Belirli order_id için açık fill var mı?

        Args:
            order_id: Hedef order ID

        Returns:
            True if order has open fills
        """
        return any(
            f["order_id"] == order_id and f["remaining_qty"] > Decimal("0")
            for f in self.fills
        )


class TVSignalConfig(BaseClientModel):
    markets: Dict[str, List[str]] = {}
    mqtt_bridge_enabled: bool = True


class TVSignalStrategy(ScriptStrategyBase):
    """
    TradingView sinyallerini dinleyen gelişmiş strategy.
    - Kaldıraç ayarlama
    - SL/TP ile pozisyon açma
    - Risk bazlı marjin hesaplama

    Bybit Perpetual Demo için optimize edilmiş versiyon.
    RogerThat'den gelen 'trading_signal' topic'ini dinler.
    """

    markets = {
        "bybit_perpetual_demo": ["CHIP-USDT", "PONS-USDT"],
    }

    # Safety remap for stale config files under conf/scripts/*.yml.
    # If config still contains LINK-USDT, normalize it to BNB-USDT.
    _MARKET_PAIR_REMAP = {
        "LINK-USDT": "BNB-USDT",
    }

    @classmethod
    def _normalize_config_markets(cls, cfg_markets: Dict[str, List[str]]) -> Dict[str, List[str]]:
        normalized: Dict[str, List[str]] = {}
        for exchange_name, pairs in (cfg_markets or {}).items():
            if not isinstance(pairs, list):
                continue
            seen = set()
            out_pairs: List[str] = []
            for pair in pairs:
                if not isinstance(pair, str):
                    continue
                mapped = cls._MARKET_PAIR_REMAP.get(pair, pair)
                if mapped not in seen:
                    seen.add(mapped)
                    out_pairs.append(mapped)
            if out_pairs:
                normalized[exchange_name] = out_pairs
        return normalized

    @classmethod
    def init_markets(cls, config: BaseClientModel):
        try:
            cfg_markets = getattr(config, "markets", None)
            if isinstance(cfg_markets, dict) and cfg_markets:
                normalized = cls._normalize_config_markets(cfg_markets)
                if normalized:
                    cls.markets = normalized
        except Exception:
            pass

    # Exchange name mapping: webhook'tan gelen isim -> Hummingbot connector ismi
    EXCHANGE_MAPPING = {
        # --- OKX ---
        "okx_perpetual": "okx_perpetual",
        "okx": "okx_perpetual",
        "okx_perpetual_demo": "okx_perpetual",
        # Eski Binance isimleri → OKX (geriye uyum; Bybit backend'de kullanılmaz)
        "binance_perpetual_testnet": "okx_perpetual",
        "binance_perpetual": "okx_perpetual",
        # --- Bybit ---
        "bybit_perpetual_demo": "bybit_perpetual_demo",
        "bybit_perpetual": "bybit_perpetual",
        "bybit": "bybit_perpetual",  # normalize_exchange_name + backend ile netleşir
        "bybit_demo": "bybit_perpetual_demo",
        "bybit_live": "bybit_perpetual",
    }

    # Internal event names for core handlers (exchange-agnostic)
    INTERNAL_EVENT_ORDER_UPDATE = "ORDER_UPDATE"
    INTERNAL_EVENT_ACCOUNT_UPDATE = "ACCOUNT_UPDATE"

    def __init__(self, connectors, config=None):
        super().__init__(connectors, config)
        self._mqtt_subscriber = None
        self._direct_mqtt_client = None
        self._direct_mqtt_connected = False
        self._direct_mqtt_last_attempt = 0
        self._external_event_listener_ready = False
        self._initialized = False
        self._pending_signals = []  # Queue for MQTT signals
        self._last_mqtt_message_ts = 0
        self._last_mqtt_stale_log = 0
        self._last_rogerthat_signal_ts = 0
        self._last_mqtt_bridge_mismatch_log = 0
        self._rogerthat_signal_topic_pattern = os.getenv(
            "MQTT_ROGERTHAT_SIGNAL_TOPIC", "rogerthat/+/signal_rx"
        ).strip()
        self._signal_retry_max = 20
        self._signal_retry_delay = 5
        self._signal_retry_backoff = 2
        # ⏱️ Backoff ÜST SINIRI. Kap olmadan delay = 5 * 2^(n-1) büyüyor:
        # retry 15 → ~1 gün, retry 20 → ~30 gün, 20 retry toplamı ~61 gün. Yani
        # çözülemeyen bir sembol pratikte ASLA düşmez, queue'da sonsuza dek kalır
        # (canlı kanıt: DOTUSD.P retry=7/20 delay=320s ve büyümeye devam ediyordu).
        self._signal_retry_delay_max = int(
            os.getenv("SIGNAL_RETRY_DELAY_MAX", "300") or 300
        )
        # ── 📁 ARŞİV BAKIMI ──
        # Canlı ölçüm (2026-07-28 VPS): signal_archive 11.694 dosya / 47 MB,
        # position_archive 12.978 dosya / 52 MB, perfill_archive 16 MB — en eskisi
        # 2026-03-30. HİÇ prune yok. Her auto-detect bu dizinde glob yapıyordu.
        # Bir pair+side için aday okuma sayısı (en yeniden geriye)
        self.ARCHIVE_SCAN_LIMIT = int(
            os.getenv("ARCHIVE_SCAN_LIMIT", "40") or 40
        )
        # Disk temizliği: bu günden eski arşiv dosyalarını sil (0 = kapalı)
        self.ARCHIVE_RETENTION_DAYS = int(
            os.getenv("ARCHIVE_RETENTION_DAYS", "7") or 7
        )
        # Her pair+side için tutulacak azami dosya sayısı (0 = sınırsız)
        self.ARCHIVE_MAX_FILES_PER_KEY = int(
            os.getenv("ARCHIVE_MAX_FILES_PER_KEY", "60") or 60
        )
        self.ARCHIVE_PRUNE_INTERVAL = int(
            os.getenv("ARCHIVE_PRUNE_INTERVAL", "3600") or 3600
        )
        self._last_archive_prune = 0.0
        # TradingView sembolü USD/USDC quote ile gelirse ve o pair connector'da YOKSA
        # aynı base'in USDT pair'ine çöz (yalnızca trading_rules'ta gerçekten varsa).
        self.SIGNAL_QUOTE_FALLBACK_USDT = (
            os.getenv("SIGNAL_QUOTE_FALLBACK_USDT", "1") or "1"
        ).strip().lower() in ("1", "true", "yes", "on")
        self._mqtt_signal_dedupe_ttl = 5
        self._mqtt_signal_recent_keys: Dict[str, float] = {}

        # 📊 MULTI-POSITION TRACKING - Her pozisyon ayrı takip edilir
        # {trading_pair: {"LONG": [pos1, pos2, ...], "SHORT": [pos1, pos2, ...]}}
        # Her pozisyon: {order_id, entry, sl, tp, amount, timestamp, 1r_reached, phase2_active, peak_price, remaining_amount}
        self._tracked_positions = {}
        self._last_position_check = 0  # Son pozisyon kontrolü zamanı
        self._last_orphan_check = 0  # Son orphan SL/TP kontrolü
        self._startup_recovery_started_at = 0

        # 🎯 SL/TP ORDER TRACKING - Her pozisyonun SL/TP order ID'leri
        # {order_id: {"sl_order_id": xxx, "tp_order_id": xxx}}
        self._sltp_orders = {}
        # 🧭 POSITION IDENTITY LEDGER - parent_order_id merkezli eşleme
        # {parent_id: {"trading_pair", "side", "cids", "child_order_ids", "child_tags", "last_update"}}
        self._position_identity_ledger: Dict[int, Dict[str, Any]] = {}
        self._identity_event_seq = 0
        self._identity_event_journal = deque(
            maxlen=int(os.getenv("IDENTITY_EVENT_JOURNAL_MAXLEN", "1000") or 1000)
        )
        self._identity_event_seen: Dict[str, float] = {}
        self.IDENTITY_EVENT_DEDUPE_TTL = int(
            os.getenv("IDENTITY_EVENT_DEDUPE_TTL", "120") or 120
        )
        # 🕒 SL/TP PENDING GUARD - API yanıtı gelene kadar naked recovery'yi bastır
        self._sltp_pending: Set[int] = set()
        # 📡 WS CONFIRMATION CACHE - WS NEW/FILLED görüldüyse yeniden yerleşimi atla
        # {parent_order_id: last_ws_timestamp}
        self._sltp_ws_confirmed: Dict[int, float] = {}
        # 🔒 SL/TP GLOBAL LOCK - paralel yerleşimlerin duplicate basmasını engelle
        self._sltp_lock = asyncio.Lock()
        # 🚫 NAKED IMMUNITY - EXPIRED/REJECTED sonrası geçici koruma
        self._naked_immunity_until: Dict[int, float] = {}

        # � CRITICAL FIX: Faz 2'ye giren pozisyonları SET ile takip et
        # Dict update'leri asyncio loop'ta hemen işlenmeyebilir!
        # Set ile atomic check/add yapılabilir
        self._phase2_active_positions = set()  # order_id'leri sakla

        # 🎯 PHASE 2 TP STRATEGY
        # If enabled: Phase 2 will NOT place a full-size TP order. Instead, when price reaches the
        # original TP level, the bot will close half of the remaining position and then trail the rest.
        # This avoids full exit at TP and prevents naked/over-sized SL due to TP fill.
        self.PHASE2_SECOND_TAKE_ENABLED = True
        self.PHASE2_SECOND_TAKE_FRACTION = Decimal("0.5")

